package offline;

import java.io.ByteArrayOutputStream;

/**
 * Analytical cleartext envelope writer. Canonical headers keep level, CID/token bytes and the
 * application key phase, drop the spin bit, narrow the packet number to the smallest width that
 * still reconstructs the same full number and minimize every header varint.
 */
public final class Canonical {

    private static final byte[] VERSION = {0, 0, 0, 1};

    private Canonical() {}

    /** Minimal QUIC varint encoding of a value in [0,2^62-1]. */
    public static byte[] varint(long value) {
        int width = varintWidth(value);
        byte[] out = new byte[width];
        long tagged = value | (widthTag(width) << (8 * width - 2));
        for (int i = 0; i < width; i++) {
            out[width - 1 - i] = (byte) (tagged >>> (8 * i));
        }
        return out;
    }

    public static int varintWidth(long value) {
        if (value < 0L) {
            throw new IllegalArgumentException("negative varint");
        }
        if (value < (1L << 6)) {
            return 1;
        }
        if (value < (1L << 14)) {
            return 2;
        }
        if (value < (1L << 30)) {
            return 4;
        }
        return 8;
    }

    private static long widthTag(int width) {
        switch (width) {
            case 1:
                return 0L;
            case 2:
                return 1L;
            case 4:
                return 2L;
            default:
                return 3L;
        }
    }

    public static void writeVarint(ByteArrayOutputStream out, long value) {
        byte[] v = varint(value);
        out.write(v, 0, v.length);
    }

    /**
     * Reconstructs the full packet number that is congruent to raw modulo 2^(8*width) and closest
     * to expected; ties choose the larger value. The result is not capped at 2^62-1.
     */
    public static long reconstruct(long raw, long expected, int width) {
        long window = 1L << (8 * width);
        long mask = window - 1;
        long candidate = (expected & ~mask) | (raw & mask);
        if (candidate + (window >>> 1) <= expected) {
            candidate += window;
        }
        return candidate;
    }

    /** Smallest packet number width in 1..4 that reconstructs pn from expected. */
    public static int numberWidth(long pn, long expected) {
        for (int width = 1; width <= 4; width++) {
            long window = 1L << (8 * width);
            if (reconstruct(pn & (window - 1), expected, width) == pn) {
                return width;
            }
        }
        return 4;
    }

    public static byte[] numberBytes(long pn, int width) {
        byte[] out = new byte[width];
        for (int i = 0; i < width; i++) {
            out[width - 1 - i] = (byte) (pn >>> (8 * i));
        }
        return out;
    }

    /**
     * Builds the canonical envelope: level 0/1 are long headers (Initial/Handshake) and level 2 is
     * the short application header.
     */
    public static byte[] envelope(int level, byte[] dcid, byte[] scid, byte[] token, int phase, long pn,
            long expected, byte[] payload) {
        int width = numberWidth(pn, expected);
        byte[] number = numberBytes(pn, width);
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        if (level == 2) {
            out.write(0x40 | ((phase & 1) << 2) | (width - 1));
            out.write(dcid, 0, dcid.length);
            out.write(number, 0, width);
        } else {
            out.write(((level == 0) ? 0xc0 : 0xe0) | (width - 1));
            out.write(VERSION, 0, VERSION.length);
            out.write(dcid.length);
            out.write(dcid, 0, dcid.length);
            out.write(scid.length);
            out.write(scid, 0, scid.length);
            if (level == 0) {
                writeVarint(out, token.length);
                out.write(token, 0, token.length);
            }
            writeVarint(out, (long) width + payload.length);
            out.write(number, 0, width);
        }
        out.write(payload, 0, payload.length);
        return out.toByteArray();
    }
}
